import React, { useEffect, useState } from 'react';
import { Navigate } from 'react-router-dom';
import { Box, CircularProgress } from '@mui/material';
import ApiService from '../../services/api';
import {
  clearPartnerPortalSession,
  persistPartnerPortalSession,
} from '../../utils/partnerPortalSession';
import { clearClientAuthSession } from '../../utils/clearClientAuthSession';
import { hasClientAuthSession, getClientAccessToken } from '../../utils/sessionAuth';

interface PartnerRouteProps {
  children: React.ReactNode;
}

const PartnerRoute: React.FC<PartnerRouteProps> = ({ children }) => {
  const [checking, setChecking] = useState(true);
  const [isPartner, setIsPartner] = useState(false);

  useEffect(() => {
    const validate = async () => {
      if (!hasClientAuthSession()) {
        setIsPartner(false);
        setChecking(false);
        return;
      }

      try {
        const response = await ApiService.request('/partner-account/me');
        const user = response?.data?.user;
        const partner = response?.data?.partner;
        if (user?.role === 'partner' && partner) {
          const token = getClientAccessToken();
          persistPartnerPortalSession(user, partner, token);
          setIsPartner(true);
        } else {
          clearPartnerPortalSession();
          setIsPartner(false);
        }
      } catch {
        clearPartnerPortalSession();
        clearClientAuthSession();
        setIsPartner(false);
      } finally {
        setChecking(false);
      }
    };

    validate();
  }, []);

  if (checking) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (!isPartner) {
    return <Navigate to="/login" replace />;
  }

  return <>{children}</>;
};

export default PartnerRoute;
