import React from 'react';
import {
  Box,
  Button,
  Chip,
  LinearProgress,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import { alpha, useTheme } from '@mui/material/styles';
import { Link as RouterLink } from 'react-router-dom';
import type { MeasurementCompleteness } from '../../utils/measurementCompleteness';

type MeasurementCompletenessRingProps = {
  completeness: MeasurementCompleteness;
  compact?: boolean;
  title?: string;
  /** When false, hide CTA / dimension deep-links (observer roles). */
  interactive?: boolean;
};

const MeasurementCompletenessRing: React.FC<MeasurementCompletenessRingProps> = ({
  completeness,
  compact = false,
  title = 'Measurement progress',
  interactive = true,
}) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const { percent, completedCount, totalCount, dimensions, nextCta } = completeness;
  const ringColor = percent >= 80
    ? theme.palette.success.main
    : percent >= 40
      ? theme.palette.warning.main
      : theme.palette.primary.main;

  return (
    <Paper
      variant="outlined"
      sx={{
        p: compact ? 1.5 : 2,
        mb: 2,
        background: isDark
          ? alpha(theme.palette.primary.main, 0.06)
          : 'linear-gradient(135deg, #ffffff 0%, #f0fdf4 70%, #f8fafc 100%)',
      }}
    >
      <Stack
        direction={{ xs: 'column', sm: 'row' }}
        spacing={2}
        alignItems={{ xs: 'stretch', sm: 'center' }}
      >
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, minWidth: compact ? 140 : 180 }}>
          <Box
            aria-hidden
            sx={{
              width: compact ? 72 : 88,
              height: compact ? 72 : 88,
              borderRadius: '50%',
              background: `conic-gradient(${ringColor} ${percent * 3.6}deg, ${alpha(theme.palette.divider, 0.35)} 0deg)`,
              p: '5px',
              flexShrink: 0,
            }}
          >
            <Box
              sx={{
                width: '100%',
                height: '100%',
                borderRadius: '50%',
                bgcolor: 'background.paper',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <Typography variant={compact ? 'h6' : 'h5'} sx={{ fontWeight: 800, lineHeight: 1 }}>
                {percent}%
              </Typography>
            </Box>
          </Box>
          <Box>
            <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
              {title}
            </Typography>
            <Typography variant="caption" color="text.secondary" display="block">
              {completedCount} of {totalCount} measurement steps ready
            </Typography>
            {interactive && nextCta ? (
              <Button
                component={RouterLink}
                to={nextCta.path}
                size="small"
                variant="contained"
                sx={{ mt: 1 }}
              >
                {nextCta.label}
              </Button>
            ) : interactive ? (
              <Chip size="small" color="success" label="Ready to report" sx={{ mt: 1 }} />
            ) : (
              <Chip
                size="small"
                color={percent >= 80 ? 'success' : 'default'}
                label={percent >= 80 ? 'Mostly complete' : 'In progress'}
                sx={{ mt: 1 }}
              />
            )}
          </Box>
        </Box>

        {!compact ? (
          <Stack spacing={1} sx={{ flex: 1, width: '100%' }}>
            {dimensions.map((dim) => (
              <Box key={dim.id}>
                <Stack direction="row" justifyContent="space-between" sx={{ mb: 0.35 }}>
                  <Typography variant="caption" sx={{ fontWeight: 600 }}>
                    {dim.label}
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    {dim.complete ? 'Done' : dim.hint}
                  </Typography>
                </Stack>
                <LinearProgress
                  variant="determinate"
                  value={dim.complete ? 100 : 12}
                  color={dim.complete ? 'success' : 'inherit'}
                  sx={{ height: 6, borderRadius: 3 }}
                />
              </Box>
            ))}
          </Stack>
        ) : (
          <Stack direction="row" spacing={0.75} useFlexGap flexWrap="wrap">
            {dimensions.map((dim) => (
              <Chip
                key={dim.id}
                size="small"
                color={dim.complete ? 'success' : 'default'}
                variant={dim.complete ? 'filled' : 'outlined'}
                label={dim.label}
                {...(interactive
                  ? { component: RouterLink, to: dim.path, clickable: true }
                  : {})}
              />
            ))}
          </Stack>
        )}
      </Stack>
    </Paper>
  );
};

export default MeasurementCompletenessRing;
