import React from 'react';
import { Box, Grid, Paper, Typography } from '@mui/material';
import { GHG_SCOPE_COLORS } from '../../constants/carbonVisualization';
import { getGlossaryIllustration } from '../../constants/glossaryIllustrations';
import { getGlossaryTerm } from '../../constants/glossaryTerms';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import { SCOPE_EXPLAINER_STRIP_LOCALE } from '../../i18n/glossaryLocale';
import PlainLanguageExplainer from './PlainLanguageExplainer';

const SCOPE_ITEMS = [
  { termId: 'scope1', color: GHG_SCOPE_COLORS.scope1.fill },
  { termId: 'scope2', color: GHG_SCOPE_COLORS.scope2.fill },
  { termId: 'scope3', color: GHG_SCOPE_COLORS.scope3.fill },
] as const;

const ScopeExplainerStrip: React.FC = () => {
  const { locale } = useReadinessLocale();
  const ui = SCOPE_EXPLAINER_STRIP_LOCALE[locale];

  return (
    <Paper variant="outlined" sx={{ p: 2, mb: 3 }} data-testid="scope-explainer-strip">
      <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
        {ui.title}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {ui.subtitle}
      </Typography>

      <Grid container spacing={2}>
        {SCOPE_ITEMS.map(({ termId, color }) => {
          const term = getGlossaryTerm(termId, locale);
          const illustration = getGlossaryIllustration(termId, locale);
          const label = term?.term
            ?? GHG_SCOPE_COLORS[termId as keyof typeof GHG_SCOPE_COLORS]?.label
            ?? termId;
          return (
            <Grid item xs={12} md={4} key={termId}>
              <Box
                sx={{
                  height: '100%',
                  border: 1,
                  borderColor: 'divider',
                  borderRadius: 1,
                  overflow: 'hidden',
                  display: 'flex',
                  flexDirection: 'column',
                }}
              >
                {illustration ? (
                  <Box
                    sx={{
                      width: '100%',
                      height: 120,
                      borderBottom: 3,
                      borderColor: color,
                      bgcolor: 'action.hover',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      p: 0.5,
                    }}
                  >
                    <Box
                      component="img"
                      src={illustration.src}
                      alt=""
                      aria-hidden
                      sx={{
                        width: '100%',
                        height: '100%',
                        objectFit: 'contain',
                      }}
                    />
                  </Box>
                ) : null}
                <Box sx={{ p: 1.5, display: 'flex', flexDirection: 'column', gap: 0.75, flex: 1 }}>
                  <PlainLanguageExplainer termId={termId} variant="heading">
                    {label}
                  </PlainLanguageExplainer>
                  {term?.plain ? (
                    <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.45 }}>
                      {term.plain}
                    </Typography>
                  ) : null}
                </Box>
              </Box>
            </Grid>
          );
        })}
      </Grid>
    </Paper>
  );
};

export default ScopeExplainerStrip;
